
"use client";

// Generated by philote from component SlotPicker. SlotPickerBody's body is
// written by a model and pinned in philote.lock (D-019).
/* eslint-disable @typescript-eslint/no-unused-vars -- every component gets the same imports */
import Link from "next/link";
import { useEffect, useRef, useState, useTransition } from "react";

import * as Icons from "lucide-react";
import { toast } from "sonner";

import { formatBool, formatDate, formatDateTime } from "@/lib/format";
import type { SlotPickerProps } from "@/lib/reads";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import {
    Card,
    CardAction,
    CardContent,
    CardDescription,
    CardFooter,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";

import Mark from "@/components/common/mark";

import { book, type BookResult } from "@/lib/actions/slot-picker-call";

// The wrapper hands the body its props, and what the template places beside them.
export default function SlotPicker(props: SlotPickerProps) {
    return <SlotPickerBody {...props} book={book} />;
}

// The spec's words for SlotPicker, in order. The body shows every one.
const says = ["Pick a time"] as const;

function SlotPickerBody({ open, book }: SlotPickerProps & { book: (input: { slot: string }) => Promise<BookResult> }): React.ReactNode {
    const [booked, setBooked] = useState<Record<string, { id: string; booked_at: string; note?: string; slot_id: string; client_id: string }>>({});
    const [pendingId, setPendingId] = useState<string | null>(null);
    const [isPending, startTransition] = useTransition();

    const handleBook = (slot: string) => {
      if (booked[slot] || pendingId) return;
      setPendingId(slot);
      startTransition(async () => {
        try {
          const result = await book({ slot });
          if (result.ok) {
            setBooked((prev) => ({ ...prev, [slot]: result.value }));
          } else {
            toast.error(result.error);
          }
        } finally {
          setPendingId(null);
        }
      });
    };

    return (
      <section className="relative w-full overflow-hidden bg-linear-to-b from-primary/10 via-background to-background">
        <div
          aria-hidden
          className="pointer-events-none absolute -top-24 -right-24 size-72 rounded-full bg-accent/40 blur-3xl"
        />
        <div
          aria-hidden
          className="pointer-events-none absolute -bottom-32 -left-20 size-80 rounded-full bg-primary/10 blur-3xl"
        />
        <div className="relative mx-auto flex max-w-5xl flex-col gap-8 px-4 py-10 sm:px-6 sm:py-16">
          <div className="flex items-center gap-3">
            <span className="flex size-10 items-center justify-center rounded-xl bg-primary/15 text-primary">
              <Icons.CalendarClock className="size-5" />
            </span>
            <h2 className="font-heading text-2xl font-semibold tracking-tight text-foreground sm:text-3xl">
              {says[0]}
            </h2>
          </div>

          <ul className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {open.map((slot) => {
              const done = booked[slot.id];
              const busy = isPending && pendingId === slot.id;
              return (
                <li key={slot.id}>
                  <Card
                    className={cn(
                      "h-full transition-all",
                      done ? "ring-2 ring-primary/60 bg-primary/5" : "hover:shadow-md"
                    )}
                  >
                    <CardHeader>
                      <div className="flex items-center gap-3">
                        <Mark name={slot.service.name} className="size-10 shrink-0" />
                        <CardTitle className="font-heading min-w-0">
                          <Link
                            href={slot.service.href}
                            className="truncate text-card-foreground underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
                          >
                            {slot.service.name}
                          </Link>
                        </CardTitle>
                      </div>
                      {done ? (
                        <CardAction>
                          <span className="flex size-7 items-center justify-center rounded-full bg-primary text-primary-foreground">
                            <Icons.Check className="size-4" />
                          </span>
                        </CardAction>
                      ) : null}
                    </CardHeader>
                    <CardContent>
                      <button
                        type="button"
                        onClick={() => handleBook(slot.id)}
                        disabled={!!done || (pendingId !== null && pendingId !== slot.id) || busy}
                        aria-busy={busy}
                        aria-pressed={!!done}
                        className={cn(
                          "flex w-full items-center gap-3 rounded-lg border px-4 py-3 text-left font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                          done
                            ? "border-primary bg-primary text-primary-foreground"
                            : "bg-background text-foreground hover:bg-accent hover:border-primary/50 disabled:opacity-60",
                          busy && "animate-pulse"
                        )}
                      >
                        {busy ? (
                          <Icons.Loader2 className="size-4 shrink-0 animate-spin" />
                        ) : (
                          <Icons.Clock className="size-4 shrink-0" />
                        )}
                        <span>{formatDateTime(slot.starts_at)}</span>
                      </button>
                    </CardContent>
                    {done ? (
                      <>
                        <Separator />
                        <CardFooter className="flex flex-col items-start gap-2">
                          <Badge variant="secondary" className="gap-1">
                            <Icons.CalendarCheck className="size-3.5" />
                            {formatDateTime(done.booked_at)}
                          </Badge>
                          {done.note ? (
                            <p className="text-sm text-muted-foreground">{done.note}</p>
                          ) : null}
                        </CardFooter>
                      </>
                    ) : null}
                  </Card>
                </li>
              );
            })}
          </ul>
        </div>
      </section>
    );
}
